function getArticleForWord(w){if(!w||w.length===0)return'a';let L=w.toLowerCase();if(/^([aeiou]|hour|honest|honor|heir|herb)/i.test(L)&&!/^uni|^use|^usu|^utili|^euro/i.test(L))return'an';return'a';}
function capitalizeFirstLetter(s){if(!s||s.length===0)return s;return s.charAt(0).toUpperCase()+s.slice(1);}
function processFieldValue(v,k){if(!v||v.length===0)return v;if(k==='name')return capitalizeFirstLetter(v);return v;}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function showScreen(id){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.getElementById(id).classList.add('active');window.scrollTo(0,0);}
