function showScoreScreen(t,s,tot,replay){document.getElementById('score-number').textContent=s+'/'+tot;let emoji=s===tot?'🏆':s>=Math.floor(tot/2)?'🌟':'👍';document.getElementById('score-emoji').textContent=emoji;document.getElementById('score-title').textContent=s===tot?'Perfect!':s>=Math.floor(tot/2)?'Good work!':'Keep practicing!';document.getElementById('score-sub').textContent='You finished '+t;document.getElementById('score-message').innerHTML='You got '+s+' out of '+tot+' correct.';document.getElementById('score-replay-btn').onclick=()=>{replay();showScreen('screen-score');};showScreen('screen-score');}
function renderHomeByLevel(){const c=document.getElementById('dynamic-cards-container');if(currentLevel==='beginner'){c.innerHTML='<div class="section-label">📘 Beginner Practice Drills</div><div class="cards-grid"><div class="ex-card" onclick="startBeginnerFindError()"><div class="ex-icon">🔍</div><div class="ex-name">Find the Error</div><div class="ex-desc">Punctuation · Articles · Spelling</div><div class="ex-badge">Free</div></div><div class="ex-card" onclick="startFixOrder()"><div class="ex-icon">🔀</div><div class="ex-name">Fix the Order</div><div class="ex-desc">Tap words to build sentences</div><div class="ex-badge">Free</div></div><div class="ex-card" onclick="startMadlibs()"><div class="ex-icon">🎭</div><div class="ex-name">Silly Scribbles</div><div class="ex-desc">Fill blanks to make stories</div><div class="ex-badge">Free</div></div><div class="ex-card" onclick="startStory()"><div class="ex-icon">📖</div><div class="ex-name">Story Starter</div><div class="ex-desc">Finish the story</div><div class="ex-badge">Free</div></div></div>';}else if(currentLevel==='intermediate'){c.innerHTML='<div class="section-label" style="color:#2b5e3b;">🌟 Intermediate Practice</div><div class="cards-grid"><div class="ex-card" onclick="startIntermediateFindError()"><div class="ex-icon">🔍</div><div class="ex-name">Find the Error</div><div class="ex-desc">Verb Forms & Irregular Past</div><div class="ex-badge">Free</div></div><div class="ex-card" onclick="startShrinkIt()"><div class="ex-icon">📝</div><div class="ex-name">Shrink It</div><div class="ex-desc">Rewrite rambling sentences</div><div class="ex-badge">Free</div></div><div class="ex-card" onclick="startThoughtPrompt()"><div class="ex-icon">💭</div><div class="ex-name">Thought Prompt</div><div class="ex-desc">Write 5 sentences on a topic</div><div class="ex-badge">Free</div></div></div>';}else{c.innerHTML='<div class="section-label" style="color:#6b2e5f;">🔒 Advanced (Preview)</div><div class="topic-preview-grid">'+EXERCISE_DATA.advancedTopics.map(t=>'<div class="topic-card"><div class="topic-icon">📘</div><div class="topic-name">'+t+'</div><div class="topic-desc">Coming soon</div><div class="ex-badge locked">🔐 Paywall</div></div>').join('')+'</div><div style="background:#f3e8f0;margin:16px;padding:16px;text-align:center;border-radius:16px;">✨ Full advanced level in next release</div>';}}
function renderBeginnerQ(){const q=EXERCISE_DATA.beginner.findError[beginnerQIndex];document.getElementById('fe-begin-progress-fill').style.width=(beginnerQIndex/5*100)+'%';document.getElementById('fe-begin-progress-text').textContent='Question '+(beginnerQIndex+1)+' of 5';document.getElementById('fe-begin-q-topic').textContent=q.topic;document.getElementById('fe-begin-sentence').textContent=q.sentence;const d=document.getElementById('fe-begin-choices');d.innerHTML='';q.choices.forEach((c,i)=>{const b=document.createElement('button');b.className='choice-btn';b.innerHTML='<span class="choice-letter">'+String.fromCharCode(65+i)+'</span>'+c.text;b.onclick=()=>{if(beginnerAnswered)return;beginnerAnswered=true;if(c.correct)beginnerScore++;document.querySelectorAll('#fe-begin-choices .choice-btn').forEach(b=>b.disabled=true);document.querySelectorAll('#fe-begin-choices .choice-btn').forEach((b,j)=>{if(q.choices[j].correct)b.classList.add('correct');});if(!c.correct)b.classList.add('wrong');const fb=document.getElementById('fe-begin-feedback');fb.classList.add('show',c.correct?'correct':'wrong');document.getElementById('fe-begin-feedback-main').textContent=c.correct?'✓ Correct!':'✗ Not quite.';document.getElementById('fe-begin-feedback-explain').textContent='📚 '+q.explain;document.getElementById('fe-begin-next-btn').classList.add('visible');};d.appendChild(b);});document.getElementById('fe-begin-feedback').className='feedback-box';document.getElementById('fe-begin-next-btn').classList.remove('visible');beginnerAnswered=false;}
