function renderShrinkQ(){const q=EXERCISE_DATA.intermediate.shrinkIt[shrinkIndex];document.getElementById('shrink-progress-fill').style.width=(shrinkIndex/2*100)+'%';document.getElementById('shrink-progress-text').textContent='Exercise '+(shrinkIndex+1)+' of 2';document.getElementById('shrink-sentence').textContent=q.sentence;const d=document.getElementById('shrink-choices');d.innerHTML='';q.choices.forEach((c,i)=>{const b=document.createElement('button');b.className='choice-btn';b.innerHTML='<span class="choice-letter">'+String.fromCharCode(65+i)+'</span>'+c.text;b.onclick=()=>{if(shrinkAnswered)return;shrinkAnswered=true;if(c.correct)shrinkScore++;document.querySelectorAll('#shrink-choices .choice-btn').forEach(b=>b.disabled=true);document.querySelectorAll('#shrink-choices .choice-btn').forEach((b,j)=>{if(q.choices[j].correct)b.classList.add('correct');});if(!c.correct)b.classList.add('wrong');const fb=document.getElementById('shrink-feedback');fb.classList.add('show',c.correct?'correct':'wrong');document.getElementById('shrink-feedback-main').textContent=c.correct?'✓ Correct! That version is clear and concise.':'✗ That version still has issues.';document.getElementById('shrink-feedback-explain').textContent='📚 '+q.explain;document.getElementById('shrink-next-btn').classList.add('visible');};d.appendChild(b);});document.getElementById('shrink-feedback').className='feedback-box';document.getElementById('shrink-next-btn').classList.remove('visible');shrinkAnswered=false;}
