function tpSubmit(){const t=document.getElementById('tp-textarea').value.trim();const s=t.split(/[.!?]+/).filter(s=>s.trim().length>0);if(s.length<5){const fb=document.getElementById('tp-feedback');fb.classList.add('show','wrong');document.getElementById('tp-feedback-main').innerHTML='✏️ Please write at least 5 complete sentences.';return;}tpCompleted++;const fb=document.getElementById('tp-feedback');fb.classList.add('show','correct');document.getElementById('tp-feedback-main').innerHTML='✓ Great effort! You wrote 5+ sentences. Read them aloud — does each sentence express a complete thought?';document.getElementById('tp-next-btn').classList.add('visible');}
