function foRenderQ(){const q=EXERCISE_DATA.beginner.fixOrder[foQIndex];foSelectedWords=[];foCurrentWords=shuffle([...q.words]);document.getElementById('fo-progress-fill').style.width=(foQIndex/5*100)+'%';document.getElementById('fo-progress-text').textContent='Question '+(foQIndex+1)+' of 5';document.getElementById('fo-feedback').className='feedback-box';document.getElementById('fo-check-btn').disabled=false;foRenderBank();foRenderAnswer();}
function foRenderBank(){const b=document.getElementById('fo-word-bank');b.innerHTML='';foCurrentWords.forEach((w,i)=>{const c=document.createElement('button');c.className='word-chip'+(foSelectedWords.includes(i)?' used':'');c.textContent=w;c.onclick=()=>{if(!foSelectedWords.includes(i)){foSelectedWords.push(i);foRenderBank();foRenderAnswer();}};b.appendChild(c);});}
function foRenderAnswer(){const a=document.getElementById('fo-answer-area');a.innerHTML='';if(foSelectedWords.length===0){a.innerHTML='<span class="answer-placeholder">Tap words below to start...</span>';return;}foSelectedWords.forEach((idx,p)=>{const c=document.createElement('span');c.className='answer-word';c.textContent=foCurrentWords[idx];c.onclick=()=>{foSelectedWords.splice(p,1);foRenderBank();foRenderAnswer();};a.appendChild(c);});}
function foClear(){foSelectedWords=[];foRenderBank();foRenderAnswer();document.getElementById('fo-feedback').className='feedback-box';}
function foCheck(){const q=EXERCISE_DATA.beginner.fixOrder[foQIndex];const ua=foSelectedWords.map(i=>foCurrentWords[i]).join(' ');const c=ua===q.answer;if(c)foScore++;const fb=document.getElementById('fo-feedback');fb.classList.add('show',c?'correct':'wrong');document.getElementById('fo-feedback-main').textContent=c?'✓ Perfect!':'✗ Not quite.';document.getElementById('fo-feedback-explain').textContent='Correct: "'+q.answer+'"';document.getElementById('fo-check-btn').disabled=true;document.getElementById('fo-next-btn').classList.add('visible');}
